from sys import stdin, stdout

def count_valid_numbers(X, A, B, allowed_digits):
    mod = 10**11
    dp = [0] * mod
    dp[0] = 1

    for d in allowed_digits:
        new_dp = [0] * mod
        for i in range(mod):
            if dp[i]:
                new_dp[(i * int(d) + int(d)) % mod] += dp[i]
                new_dp[(i * int(d)) % mod] += dp[i]
        dp = new_dp

    def count_up_to(n):
        n_str = str(n)
        result = 0
        for i in range(len(n_str)):
            prefix = int(n_str[:i])
            for d in allowed_digits:
                if int(d) > prefix:
                    break
                result += dp[(prefix * int(d)) % mod]
            if int(n_str[i]) not in allowed_digits:
                break
            prefix = prefix * 10 + int(n_str[i])
            result += dp[prefix % mod]
        return result

    return count_up_to(B) - count_up_to(A - 1)

