def count_multiples(X, A, B, allowed_digits):
    @lru_cache(None)
    def dfs(pos, tight, num):
        if pos == len(allowed_digits):
            return int(num % X == 0)
        res = 0
        ub = int(tight and str(B)[pos]) if tight else 9
        for d in allowed_digits:
            if int(d) > ub:
                break
            res += dfs(pos + 1, tight and int(d) == ub, num * 10 + int(d))
        return res

    return dfs(0, True, 0)

