def count_multiples(X, A, B, allowed_digits):
    allowed_set = set(allowed_digits)

    @lru_cache(None)
    def dfs(num, pos, tight):
        if pos == len(str(B)):
            return int(num % X == 0)

        max_digit = int(str(B)[pos]) if tight else 9
        count = 0

        for d in range(max_digit + 1):
            if str(d) in allowed_set:
                new_tight = tight and d == max_digit
                count += dfs(num * 10 + d, pos + 1, new_tight)

        return count

    return dfs(0, 0, True)

