    max_length = len(str(B))

    dp = [[0] * 10 for _ in range(max_length + 1)]
    dp[0][0] = 1

    for i in range(1, max_length + 1):
        for j in range(10):
            if str(j) in allowed_set:
                dp[i][j] = sum(dp[i-1][k] for k in range(j+1)) % 1000000007

    def count_numbers(n):
        n_str = str(n)
        length = len(n_str)
        result = 0
        for i in range(length):
            for d in allowed_set:
                if int(d) <= int(n_str[i]):
                    result += dp[length-i-1][int(d)]
                else:
                    break
            if int(n_str[i]) not in allowed_set:
                break
        return result

    count_A = count_numbers(A - 1)
    count_B = count_numbers(B)

    return (count_B - count_A) % 1000000007

